	registerEnvironmentOK(t, router, "prod")
	registerEnvironmentOK(t, router, "dev")
	createRecordOK(t, router, changeRecordBody("prod", "1.0.0", "allowed", "rb", "b-1",
		entryMap(1, "feature", "t", "d")))

	first := doRequest(t, router, http.MethodGet,
		"/api/v1/release-records?environment=prod&batch_id=b-1&limit=1", "")
	cursor, _ := decodeRecordsPage(t, first)["next_cursor"].(string)
	if cursor == "" {
		t.Fatal("expected next_cursor")
	}
	// Identical normalized conditions work.
	same := doRequest(t, router, http.MethodGet,
		"/api/v1/release-records?environment=prod&batch_id=b-1&limit=1&cursor="+cursor, "")
	if same.Code != http.StatusOK {
		t.Fatalf("same filter rejected: %d %s", same.Code, same.Body.String())
	}
	mismatches := []string{
		"/api/v1/release-records?environment=dev&batch_id=b-1&limit=1&cursor=" + cursor,
		"/api/v1/release-records?environment=prod&limit=1&cursor=" + cursor,
		"/api/v1/release-records?environment=prod&batch_id=b-1&gate_status=blocked&limit=1&cursor=" + cursor,
		"/api/v1/release-records?environment=prod&batch_id=b-1&version=1.0.0&limit=1&cursor=" + cursor,
		"/api/v1/release-records?environment=prod&batch_id=b-1&limit=1&cursor=" + cursor + "x",
		"/api/v1/release-records?environment=prod&batch_id=b-1&limit=1&cursor=" + "not-a-cursor",
