		http.StatusBadRequest, store.CodeInvalidReleaseRecordQueryV1)
}

// mutateBase64 flips the final character of a raw-url-base64 string into a
// different alphabet character.
func mutateBase64(value string) string {
	alphabet := "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
	last := value[len(value)-1]
	for _, candidate := range alphabet {
		if byte(candidate) != last {
			return value[:len(value)-1] + string(candidate)
		}
	}
	return value
}

